def kv_cache_gb(batch, seq_len, n_layers, n_heads, head_dim, dtype_bytes=2):
    per_token = batch * 2 * n_layers * n_heads * head_dim * dtype_bytes
    return per_token * seq_len / (1024 ** 3)

