def schedule(requests, max_steps=100):
    active = list(requests)
    finished = set()
    log = []
    for t in range(max_steps):
        batch = [r for r in active if r not in finished]
        if not batch:
            break
        step(batch)                 # 每个 decode 步统一算
        for r in batch:
            if r.done():
                finished.add(r)     # 出 EOS 立即释放
        log.append((t, list(batch)))
    return log

